bash -lc node -e '
const fs=require("fs"), zlib=require("zlib");
function ascii85Decode(s){
  s=s.replace(/\s/g,"");
  if(s.endsWith("~>")) s=s.slice(0,-2);
  const out=[];
  for(let i=0;i<s.length;){
    if(s[i]==="z"){out.push(0,0,0,0);i++;continue;}
    const chunk=s.slice(i,i+5); i+=5;
    const n=chunk.length;
    let v=0;
    for(let j=0;j<5;j++){ const c=j<n?chunk.charCodeAt(j)-33:117; v=v*85+c; }
    const b=[(v>>>24)&255,(v>>>16)&255,(v>>>8)&255,v&255];
    out.push(...b.slice(0,n-1));
  }
  return Buffer.from(out);
}
for(const f of fs.readdirSync("/app/documents").filter(x=>x.endsWith(".pdf"))){
  const raw=fs.readFileSync("/app/documents/"+f,"latin1");
  const m=[...raw.matchAll(/stream\r?\n([\s\S]*?)endstream/g)];
  console.log("=== "+f+" streams:"+m.length);
  for(const g of m){
    try{
      const dec=ascii85Decode(g[1]);
      let inf;
      try{inf=zlib.inflateSync(dec);}catch(e){inf=dec;}
      console.log(inf.toString("latin1").slice(0,4000));
    }catch(e){console.log("ERR",e.message);}
  }
  console.log();
}
'

