const fs=require("fs"), zlib=require("zlib");
for(const f of ["T0r6Ou8zvqTA.pdf","UsN9tVTKskms.pdf","wIQEB5nR79b2.pdf","dvkRkFVFhHga.pdf"]){
  const raw=fs.readFileSync("/app/documents/"+f);
  const txt=raw.toString("latin1");
  console.log("=== "+f);
  const re=/\/Length\s+(\d+)>>\s*stream\r?\n/g;
  let m;
  while((m=re.exec(txt))){
    const len=parseInt(m[1]);
    const start=m.index+m[0].length;
    const data=raw.slice(start,start+len);
    try{
      const inf=zlib.inflateSync(data);
      const s=inf.toString("latin1");
      console.log("  [stream len="+len+" inflated="+inf.length+"]");
      // extract text in parens
      const tj=[...s.matchAll(/\(([^\\)]*)\)\s*Tj/g)].map(x=>x[1]);
      console.log("  TEXTS: "+JSON.stringify(tj.slice(0,60)));
      if(s.length<2000) console.log(s.slice(0,1500));
    }catch(e){ console.log("  [stream len="+len+"] inflate fail: "+e.message); }
  }
}
'

